parameters.jsCode:
const response = $input.first().json;
const incoming = $('Execute Workflow Trigger').first().json;
let parsed = {};

try {
  const content = response.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {
    intent: 'general_inquiry',
    category: 'professional',
    detected_language: 'English',
    priority: 'normal',
    should_reply: true,
    requires_approval: true,
    reasoning: 'Fallback classification due to JSON parsing error.'
  };
}

// Force no-reply on promotional or spam emails
if (parsed.category === 'promotional' || parsed.category === 'spam_suspicious') {
  parsed.should_reply = false;
}

return [{
  json: {
    ...incoming,
    classification: parsed,
    tokensUsed: response.usage || {}
  }
}];
